    ///     Event Listener for Track.
    /// </summary>
    [Parameter]
    [JsonIgnore]
    public EventCallback<TrackEvent> OnTrack { get; set; }
   
    /// <summary>
    ///     Used in JavaScript layer to determine if the event listener is registered.
    /// </summary>
    public bool HasTrackListener => OnTrack.HasDelegate;
    
    /// <summary>
    ///     JavaScript-Invokable Method for internal use only.
    /// </summary>
    [JSInvokable]
    public async Task OnJsTrackError(IJSStreamReference jsStreamRef)
    {
        if (IsDisposed)
        {
            // cancel if the component is disposed
            return;
        }
    
        TrackErrorEvent? trackErrorEvent = await jsStreamRef.ReadJsStreamReference<TrackErrorEvent>();
        if (trackErrorEvent is not null)
        {
            await OnTrackError.InvokeAsync(trackErrorEvent);
        }
    }
    
    /// <summary>
    ///     <a target="_blank" href="https://docs.geoblazor.com/pages/classes/dymaptic.GeoBlazor.Pro.Components.Widgets.TrackWidget.html#trackwidgetontrackerror-property">GeoBlazor Docs</a>
    ///     Event Listener for TrackError.
    /// </summary>
    [Parameter]
    [JsonIgnore]
    public EventCallback<TrackErrorEvent> OnTrackError { get; set; }
   
    /// <summary>
    ///     Used in JavaScript layer to determine if the event listener is registered.
    /// </summary>
    public bool HasTrackErrorListener => OnTrackError.HasDelegate;
    
#endregion


    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Graphic graphic:
                if (graphic != Graphic)
                {
                    Graphic = graphic;
                    ModifiedParameters[nameof(Graphic)] = Graphic;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case TrackViewModel viewModel:
                if (viewModel != ViewModel)
                {
                    ViewModel = viewModel;
                    ModifiedParameters[nameof(ViewModel)] = ViewModel;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Graphic _:
                Graphic = null;
                ModifiedParameters[nameof(Graphic)] = Graphic;
                return true;
            case TrackViewModel _:
                ViewModel = null;
                ModifiedParameters[nameof(ViewModel)] = ViewModel;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        Graphic?.ValidateRequiredGeneratedChildren();
        ViewModel?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
